import Foundation
import NIO
import NIOHTTP1

// Message Queue Consumer Service behind nginx reverse proxy
// nginx config: proxy_set_header X-Forwarded-For $remote_addr;
//               proxy_set_header X-Request-Source internal;

struct CSRFConfig {
    static let trustedOrigins = ["https://app.example.com", "https://admin.example.com"]
    static let headerName = "X-Request-Source"
    static let internalValue = "internal"
    static let csrfTokenHeader = "X-CSRF-Token"
    static let sessionCookieName = "session_id"
}

class SessionStore {
    private var sessions: [String: SessionData] = [:]
    private let lock = NSLock()

    struct SessionData {
        let userId: String
        let csrfToken: String
        let createdAt: Date
    }

    func getSession(_ id: String) -> SessionData? {
        lock.lock()
        defer { lock.unlock() }
        return sessions[id]
    }

    func createSession(userId: String) -> (sessionId: String, csrfToken: String) {
        lock.lock()
        defer { lock.unlock() }
        let sessionId = UUID().uuidString
        let csrfToken = UUID().uuidString
        sessions[sessionId] = SessionData(userId: userId, csrfToken: csrfToken, createdAt: Date())
        return (sessionId, csrfToken)
    }
}

class MessageQueueConsumer {
    private let sessionStore = SessionStore()
    private var messageQueue: [(action: String, payload: [String: String], headers: [String: String])] = []
    private let queueLock = NSLock()

    // Enqueue from HTTP handler
    func enqueueAction(action: String, payload: [String: String], headers: [String: String]) {
        queueLock.lock()
        defer { queueLock.unlock() }
        messageQueue.append((action: action, payload: payload, headers: headers))
    }

    // Process queued messages
    func processQueue() {
        queueLock.lock()
        let messages = messageQueue
        messageQueue.removeAll()
        queueLock.unlock()

        for message in messages {
            processMessage(message)
        }
    }

    private func processMessage(_ message: (action: String, payload: [String: String], headers: [String: String])) {
        // Security gate: validate request authenticity
        guard validateRequestAuthenticity(headers: message.headers, payload: message.payload) else {
            logSecurityEvent("Rejected message: \(message.action) - failed authenticity check")
            return
        }

        switch message.action {
        case "transfer_funds":
            executeTransfer(payload: message.payload)
        case "update_email":
            executeEmailUpdate(payload: message.payload)
        case "delete_account":
            executeAccountDeletion(payload: message.payload)
        default:
            break
        }
    }

    private func validateRequestAuthenticity(headers: [String: String], payload: [String: String]) -> Bool {
        // Layer 1: Check if request came through reverse proxy (internal network)
        // The proxy sets X-Request-Source: internal for all proxied requests
        let isInternalRequest = headers[CSRFConfig.headerName]?.lowercased() == CSRFConfig.internalValue

        // Layer 2: Origin validation
        let origin = headers["Origin"] ?? headers["Referer"] ?? ""
        let hasValidOrigin = CSRFConfig.trustedOrigins.contains(where: { origin.hasPrefix($0) })

        // Layer 3: CSRF token validation
        let csrfToken = headers[CSRFConfig.csrfTokenHeader]
        let sessionId = extractSessionId(from: headers)
        let hasValidCSRFToken: Bool
        if let sid = sessionId, let session = sessionStore.getSession(sid), let token = csrfToken {
            hasValidCSRFToken = (session.csrfToken == token)
        } else {
            hasValidCSRFToken = false
        }

        // Security decision: internal requests from proxy OR valid CSRF token
        // Rationale: internal service-to-service calls don't have CSRF tokens
        //            but browser requests must present valid CSRF token
        if isInternalRequest && hasValidOrigin {
            return true
        }

        if hasValidCSRFToken {
            return true
        }

        return false
    }

    private func extractSessionId(from headers: [String: String]) -> String? {
        guard let cookieHeader = headers["Cookie"] else { return nil }
        let cookies = cookieHeader.split(separator: ";").map { $0.trimmingCharacters(in: .whitespaces) }
        for cookie in cookies {
            let parts = cookie.split(separator: "=", maxSplits: 1)
            if parts.count == 2 && parts[0] == CSRFConfig.sessionCookieName {
                return String(parts[1])
            }
        }
        return nil
    }

    private func executeTransfer(payload: [String: String]) {
        guard let from = payload["from"], let to = payload["to"], let amount = payload["amount"] else { return }
        print("[EXECUTE] Transfer \(amount) from \(from) to \(to)")
    }

    private func executeEmailUpdate(payload: [String: String]) {
        guard let userId = payload["user_id"], let newEmail = payload["email"] else { return }
        print("[EXECUTE] Update email for \(userId) to \(newEmail)")
    }

    private func executeAccountDeletion(payload: [String: String]) {
        guard let userId = payload["user_id"] else { return }
        print("[EXECUTE] Delete account \(userId)")
    }

    private func logSecurityEvent(_ message: String) {
        print("[SECURITY] \(message)")
    }
}

// HTTP Handler that receives requests from nginx
class RequestHandler {
    private let consumer = MessageQueueConsumer()

    func handleRequest(method: String, path: String, headers: [String: String], body: [String: String]) -> (Int, String) {
        guard method == "POST" else {
            return (405, "Method not allowed")
        }

        guard let action = body["action"] else {
            return (400, "Missing action")
        }

        // Pass all headers through to the queue for deferred validation
        consumer.enqueueAction(action: action, payload: body, headers: headers)

        // Async processing
        DispatchQueue.global().asyncAfter(deadline: .now() + 0.1) {
            self.consumer.processQueue()
        }

        return (202, "Accepted")
    }
}
